with recent_subscriptions as (select *, date_format(end_date, 'yyyy-MM-dd') as end_date_label from subscriptions where end_date between '2023-06-24' and '2023-11-11' or monthly_fee >= 90), Agg as (select date_trunc('MONTH', end_date) as end_month, sum(case when plan = 'enterprise' then monthly_fee else 0 end) as enterprise_monthly_fee from recent_subscriptions group by date_trunc('MONTH', end_date)) select end_month, enterprise_monthly_fee from Agg
